-- public.lair_site(p_world uuid, p_kind text, p_self integer, p_looks integer, OUT x integer, OUT y integer)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.lair_site(p_world uuid, p_kind text, p_self integer DEFAULT NULL::integer, p_looks integer DEFAULT 400, OUT x integer, OUT y integer)
 RETURNS record
 LANGUAGE plpgsql
AS $function$
declare v_cells int[]; v_c int; k record; v_size int; v_step int; v_fine int; i int; gx int; gy int; c record; f record; v_isle int;
begin
  select * into k from lair_kinds() lk where lk.id = p_kind;
  select w.size into v_size from world w where w.id = p_world;
  if k.id is null or v_size is null then return; end if;
  if k.site <> 'peak' then
    for i in 1 .. p_looks loop
      -- On its island's chart cells (`monster_isle`), for a kind kept to one; anywhere for any other.
      if i = 1 and monster_isle(k.species) is not null then
        v_cells := array(select r.cy * 256 + a from chart_region r cross join generate_series(0, 255) a
                          where get_byte(r.cells, a) = monster_isle(k.species));
      end if;
      if cardinality(v_cells) > 0 then
        v_c := v_cells[1 + floor(random() * cardinality(v_cells))::int];
        gx := least(v_size - 3, greatest(2, floor(((v_c % 256) + random()) * v_size / 256)::int));
        gy := least(v_size - 3, greatest(2, floor(((v_c / 256) + random()) * v_size / 256)::int));
      else
        gx := 2 + floor(random() * (v_size - 4))::int;
        gy := 2 + floor(random() * (v_size - 4))::int;
      end if;
      if lair_site_ok(p_world, p_kind, gx, gy, p_self) then x := gx; y := gy; return; end if;
    end loop;
    return;
  end if;
  v_isle := monster_isle(k.species);
  v_step := greatest(1, v_size / 128);
  v_fine := greatest(1, v_step / 4);
  for c in
    select g.gx, g.gy from (
      select a as gx, b as gy from generate_series(2, v_size - 3, v_step) a cross join generate_series(2, v_size - 3, v_step) b
       where v_isle is null or region_at(p_world, a + 0.5, b + 0.5) = v_isle) g
     order by centre_height(p_world, g.gx, g.gy) desc, g.gx, g.gy limit 12
  loop
    for f in
      select a as fx, b as fy from generate_series(greatest(2, c.gx - v_step), least(v_size - 3, c.gx + v_step), v_fine) a
        cross join generate_series(greatest(2, c.gy - v_step), least(v_size - 3, c.gy + v_step), v_fine) b
       order by centre_height(p_world, a, b) desc, a, b
    loop
      if lair_site_ok(p_world, p_kind, f.fx, f.fy, p_self) then x := f.fx; y := f.fy; return; end if;
    end loop;
  end loop;
end $function$
